 "content": "def transform(grid):
    """Project the center row and center column of every solid 3x3 marker."""
    h, w = len(grid), len(grid[0])
    objects = []
    protected = set()
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color == 0:
                continue
            if all(grid[rr][cc] == color
                   for rr in range(r, r + 3)
                   for cc in range(c, c + 3)):
                objects.append((r + 1, c + 1, color))
                protected.update((rr, cc)
                                 for rr in range(r, r + 3)
                                 for cc in range(c, c + 3))

    rays = {}
    for r, c, color in objects:
        for cc in range(w):
            rays.setdefault((r, cc), set()).add(color)
        for rr in range(h):
            rays.setdefault((rr, c), set()).add(color)

    out = [row[:] for row in grid]
    for (r, c), colors in rays.items():
        if (r, c) in protected:
            continue
        out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    return out
